function PreviewLoginBlock({name}:ExampleProps){
const trigger=useRef<React.ComponentRef<typeof View>>(null);
const [checked,setChecked]=useState(false);
const [value,setValue]=useState('buy');
const [open,setOpen]=useState(false);
const [message,setMessage]=useState('');
function preview(){switch(name){case "LoginBlock":return <C.Stack><C.Button ref={trigger} onPress={()=>setOpen(true)}>Log in</C.Button><C.GestureSheet open={open} onOpenChange={setOpen} returnFocusRef={trigger} title="Log in" contentMode="custom" enableDynamicSizing><View style={{padding:16}}><C.LoginBlock lastUsed={value==='apple'||value==='google'?value:'twitter'} analyticsEnabled={checked} onAnalyticsChange={setChecked} onLogin={provider=>{setValue(provider);setMessage('Selected '+(provider==='twitter'?'X':provider==='apple'?'Apple':'Google'));setOpen(false);}} onClose={()=>setOpen(false)}/></View></C.GestureSheet></C.Stack>;
default:return <C.Text>Platform example unavailable.</C.Text>;}}
return <C.Stack style={['List','Table','OutcomeChart'].includes(name)?{flex:1}:undefined}>{preview()}{message&&<C.Text>{message}</C.Text>}</C.Stack>;}
